  iconv: { d: "Mengonversi teks antar pengodean karakter.", d2: "Mengonversi pengodean karakter teks dari satu codeset ke codeset lain, mis. berkas ISO-8859-1 lama ke UTF-8.", o: ["Tentukan pengodean sumber", "Tentukan pengodean tujuan", "List semua set karakter yang dikenal", "Buang karakter tidak valid alih-alih berhenti"], n: ["Kasus: pengodean lama ke UTF-8", "List pengodean yang dikenal", "Ratakan aksen menjadi ASCII"], s: ["Sukses", "Terjadi kesalahan"] },
