  id: { d: "Menampilkan ID pengguna dan grup nyata serta efektif.", d2: "Menampilkan identitas pengguna dan grup: UID/GID nyata dan efektif serta semua keanggotaan grup untuk pengguna saat ini atau pengguna yang disebutkan.", o: ["Tampilkan hanya user ID efektif", "Tampilkan hanya group ID efektif", "Tampilkan semua group ID", "Tampilkan nama alih-alih angka (dengan -u/-g/-G)"], n: ["UID, GID, dan grup Anda", "Hanya UID numerik", "Periksa pengguna lain", "Kasus: hanya nama grup"], s: ["Sukses", "Terjadi kesalahan"] },
  w: { d: "Menampilkan siapa yang masuk dan apa yang mereka lakukan.", d2: "Menampilkan siapa yang sedang masuk dan apa yang dilakukan setiap sesi: waktu login, waktu idle, penggunaan CPU, serta perintah saat ini untuk setiap pengguna.", o: ["Jangan cetak baris header", "Abaikan nama pengguna saat menentukan proses saat ini", "Gunakan format pendek (tanpa waktu login, JCPU, PCPU)", "Tampilkan alamat IP alih-alih hostname"], n: ["Siapa yang masuk dan apa yang mereka jalankan", "Satu pengguna, tanpa header", "Format pendek"], s: ["Sukses", "Terjadi kesalahan"] },
